import numpy as np

def solve_for_N(N):
    best_sum = -float('inf')
    # Iterate over all 2^N operation sequences
    for i in range(1 << N):
        ops = []
        for j in range(N):
            if (i >> j) & 1:
                ops.append(1) # op1: x_{n+1} = 4x_n^2, y_{n+1} = x_n
            else:
                ops.append(2) # op2: x_{n+1} = x_n/2, y_{n+1} = 1/4 - x_n

        # For this sequence of ops, we want to find x_0 such that x_N <= x_0
        # and S = sum(y_n) is maximized.
        # S(x_0) and x_N(x_0) are polynomials.
        # Let's sample x_0 in [0, 1].
        # Actually, x_n could be larger than 1, but if x_n > 1/2, 4x_n^2 will be even larger.
        # If x_n > 1/2, x_{n+1} = 4x_n^2 > 1.
        # If we use op1 many times, x_n will grow very fast.
        # To keep x_N <= x_0, x_n must not grow too much.
        # Let's try x_0 in [0, 1] with 1000 steps.
        for x0_val in np.linspace(0, 1, 1000):
            x = x0_val
            current_sum = 0
            for op in ops:
                if op == 1:
                    current_sum += x
                    x = 4 * x**2
                else:
                    current_sum += 0.25 - x
                    x = x / 2

            if x <= x0_val:
                if current_sum > best_sum:
                    best_sum = current_sum
    return best_sum

for n in range(1, 7):
    print(f"N={n}, max_sum={solve_for_N(n)}")

import numpy as np

def solve_for_N_v3(N):
    # Check more combinations of op1 and op2
    best_sum = N / 4
    # Try all possible operation sequences for small N
    for i in range(1 << N):
        ops = []
        for j in range(N):
            if (i >> j) & 1:
                ops.append(1)
            else:
                ops.append(2)

        # x_N(x_0) <= x_0
        # Let's find the range of x_0 that satisfies this.
        # For a given sequence of ops, x_N is a polynomial in x_0.
        # x_N = c * x_0^d.
        # We can just sample a large number of x_0.
        for x0 in np.linspace(0, 10, 2000):
            x = x0
            current_sum = 0
            for op in ops:
                if op == 1:
                    current_sum += x
                    x = 4 * x**2
                else:
                    current_sum += 0.25 - x
                    x = x / 2
            if x <= x0:
                if current_sum > best_sum:
                    best_sum = current_sum
    return best_sum

for n in range(1, 7):
    print(f"N={n}, max_sum={solve_for_N_v3(n)}")
